async function handleCleanupSettingsCallback(client2, update, data) {
  const userId = update.userId.toJSNumber();
  const locale = await getTelegramUserLocaleOrDefault(userId);
  if (!await isAuthenticatedAsync(userId)) {
    await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: MSG.AUTH_REQUIRED, alert: true }));
    return;
  }
  try {
    const enabled = data === "cs_set_on";
    await setSetting("auto_cleanup_orphans", String(enabled));
    process.env.AUTO_CLEANUP_ORPHANS = String(enabled);
    if (enabled) {
      startPeriodicCleanup();
    } else {
      stopPeriodicCleanup();
    }
    await client2.editMessage(update.peer, {
      message: Number(update.msgId),
      text: buildCleanupSettingsText(enabled, locale),
      buttons: buildCleanupSettingsKeyboard(enabled, locale)
    });
    await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, enabled ? "commands.auto127" : "commands.auto126") }));
  } catch (error) {
    console.error("\u{1F916} \u8BBE\u7F6E\u81EA\u52A8\u6E05\u7406\u5931\u8D25:", error);
    await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.settingFailedRetry"), alert: true }));
  }
}
async function handleDownloadWorkersCallback(client2, update, data) {
  const userId = update.userId.toJSNumber();
  const locale = await getTelegramUserLocaleOrDefault(userId);
  if (!await isAuthenticatedAsync(userId)) {
    await client2.invoke(new Api8.messages.SetBotCallbackAnswer({
      queryId: update.queryId,
      message: MSG.AUTH_REQUIRED,
      alert: true
    }));
    return;
  }
  try {
    if (data === "dw_cancel") {
      const current3 = await getCurrentDownloadWorkers();
      await client2.editMessage(update.peer, {
        message: Number(update.msgId),
        text: buildDownloadWorkersText(current3, locale),
        buttons: buildDownloadWorkersKeyboard(current3, void 0, locale)
      });
      await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.cancelled") }));
      return;
    }
    const setMatch = data.match(/^dw_set_(4|8|12|16)$/);
    if (setMatch) {
      const workers = Number(setMatch[1]);
      if (workers >= 12) {
        await client2.editMessage(update.peer, {
          message: Number(update.msgId),
          text: [
            t(locale, "commands.auto128", { value0: workers }),
            "",
            t(locale, "commands.auto129"),
            t(locale, "commands.auto130"),
            t(locale, "commands.auto131"),
            "- Telegram \u7528\u6237\u8D26\u53F7\u53EF\u80FD\u88AB\u9650\u6D41\uFF0C\u6781\u7AEF\u60C5\u51B5\u4E0B\u4F1A\u5F71\u54CD\u8D26\u53F7",
            "",
            t(locale, "commands.auto133")
          ].join("\n"),
          buttons: buildDownloadWorkersKeyboard(workers, workers, locale)
        });
        await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.secondConfirm") }));
        return;
      }
      await setSetting("telegram_download_workers", String(workers));
      await client2.editMessage(update.peer, {
        message: Number(update.msgId),
        text: `${buildDownloadWorkersText(workers, locale)}

${t(locale, "commands.auto134", { value0: "", value1: workers })}`,
        buttons: buildDownloadWorkersKeyboard(workers, void 0, locale)
      });
      await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.auto135", { value0: workers }) }));
      return;
    }
    const confirmMatch = data.match(/^dw_confirm_(12|16)$/);
    if (confirmMatch) {
      const workers = Number(confirmMatch[1]);
      await setSetting("telegram_download_workers", String(workers));
      await client2.editMessage(update.peer, {
        message: Number(update.msgId),
        text: `${buildDownloadWorkersText(workers, locale)}

${t(locale, "commands.auto136", { value0: "", value1: workers })}`,
        buttons: buildDownloadWorkersKeyboard(workers, void 0, locale)
      });
      await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.auto137", { value0: workers }), alert: true }));
    }
  } catch (error) {
    console.error("\u{1F916} \u8BBE\u7F6E\u5E76\u53D1\u4E0B\u8F7D worker \u5931\u8D25:", error);
    await client2.invoke(new Api8.messages.SetBotCallbackAnswer({
      queryId: update.queryId,
      message: t(locale, "commands.settingFailedRetry"),
      alert: true
    }));
  }
}
async function handleFileConcurrencyCallback(client2, update, data) {
  const userId = update.userId.toJSNumber();
  const locale = await getTelegramUserLocaleOrDefault(userId);
  if (!await isAuthenticatedAsync(userId)) {
    await client2.invoke(new Api8.messages.SetBotCallbackAnswer({
      queryId: update.queryId,
      message: MSG.AUTH_REQUIRED,
      alert: true
    }));
    return;
  }
  try {
    if (data === "fc_cancel") {
      const current3 = await getCurrentFileConcurrency();
      setFileDownloadConcurrency(current3);
      await client2.editMessage(update.peer, {
        message: Number(update.msgId),
        text: buildFileConcurrencyText(current3, locale),
        buttons: buildFileConcurrencyKeyboard(current3)
      });
      await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.cancelled") }));
      return;
    }
    const setMatch = data.match(/^fc_set_(1|2|3|4)$/);
    if (setMatch) {
      const concurrency2 = Number(setMatch[1]);
      if (concurrency2 === 4) {
        await client2.editMessage(update.peer, {
          message: Number(update.msgId),
          text: [
            "\u26A0\uFE0F **\u786E\u8BA4\u540C\u65F6\u4E0B\u8F7D 4 \u4E2A\u6587\u4EF6\uFF1F**",
            "",
            "\u8FD9\u662F\u6587\u4EF6\u7EA7\u6FC0\u8FDB\u5E76\u53D1\u6A21\u5F0F\uFF0C\u53EF\u80FD\u51FA\u73B0\uFF1A",
            "- Telegram \u98CE\u63A7\u6216\u9650\u6D41",
            "- \u4E91\u76D8\u4E0A\u4F20\u9650\u901F / \u5931\u8D25\u91CD\u8BD5\u589E\u591A",
            "- \u670D\u52A1\u5668\u78C1\u76D8\u548C\u7F51\u7EDC\u538B\u529B\u660E\u663E\u589E\u52A0",
            "",
            "\u5982\u679C\u53EA\u662F\u65E5\u5E38\u4E0B\u8F7D\uFF0C\u5EFA\u8BAE\u4F7F\u7528 2 \u6216 3\u3002"
          ].join("\n"),
          buttons: buildFileConcurrencyKeyboard(concurrency2, concurrency2)
        });
        await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.secondConfirm") }));
        return;
      }
      await setSetting("telegram_file_download_concurrency", String(concurrency2));
      const normalized = setFileDownloadConcurrency(concurrency2);
      await client2.editMessage(update.peer, {
        message: Number(update.msgId),
        text: `${buildFileConcurrencyText(normalized, locale)}

${t(locale, "commands.auto144", { value0: "", value1: normalized })}`,
        buttons: buildFileConcurrencyKeyboard(normalized)
      });
      await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.auto145", { value0: normalized }) }));
      return;
    }
    const confirmMatch = data.match(/^fc_confirm_4$/);
    if (confirmMatch) {
      await setSetting("telegram_file_download_concurrency", "4");
      const normalized = setFileDownloadConcurrency(4);
      await client2.editMessage(update.peer, {
        message: Number(update.msgId),
        text: `${buildFileConcurrencyText(normalized, locale)}

${t(locale, "commands.auto146", { value0: "", value1: normalized })}`,
        buttons: buildFileConcurrencyKeyboard(normalized)
      });
      await client2.invoke(new Api8.messages.SetBotCallbackAnswer({ queryId: update.queryId, message: t(locale, "commands.auto147"), alert: true }));
    }
  } catch (error) {
    console.error("\u{1F916} \u8BBE\u7F6E\u6587\u4EF6\u7EA7\u5E76\u53D1\u5931\u8D25:", error);
    await client2.invoke(new Api8.messages.SetBotCallbackAnswer({
      queryId: update.queryId,
      message: t(locale, "commands.settingFailedRetry"),
      alert: true
    }));
  }
}

